package com.hospital.smartqueue.patient.application; import com.hospital.smartqueue.common.domain.*; import com.hospital.smartqueue.common.infrastructure.AuditService; import com.hospital.smartqueue.common.security.PatientAccessContext; import com.hospital.smartqueue.hospital.infrastructure.HospitalRepository; import com.hospital.smartqueue.patient.api.*; import com.hospital.smartqueue.patient.domain.*; import com.hospital.smartqueue.patient.infrastructure.PatientRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class PatientService {private final PatientRepository patients;private final HospitalRepository hospitals;private final PatientAccessContext access;private final AuditService audit; public PatientService(PatientRepository p,HospitalRepository h,PatientAccessContext a,AuditService u){patients=p;hospitals=h;access=a;audit=u;}
 @Transactional public Patient register(UUID hospitalId,RegisterPatientRequest r){access.authorize(hospitalId,hospitalId);if(!hospitals.existsById(hospitalId))throw new NotFoundException("Requested resource was not found");Patient p=patients.save(new Patient(hospitalId,"PAT-"+UUID.randomUUID().toString().substring(0,12).toUpperCase(),r.firstName(),r.lastName(),r.dateOfBirth(),r.gender(),r.mobileNumber(),r.email(),r.address(),r.emergencyContact()));audit.record("PATIENT_REGISTERED","PATIENT",p.getId(),hospitalId,"{}");return p;}}
